-- 97 · Sociétés trouvées sur le web (annuaires de partenaires, sites des cabinets), fusionnées par SIREN.
-- Généré par scripts/providers-merge-sql.py : 12 fiches existantes complétées, 286 nouvelles en brouillon.

update public.providers p set
  website = coalesce(p.website, x.website),
  specialties = array(select distinct s from unnest(p.specialties || x.specialties) s),
  description = case when p.description like 'Société d''activités comptables%' or p.description like 'Cabinet de recrutement%'
                       or p.description is null then coalesce(x.description, p.description) else p.description end
from (values
  ('844071324', null, array['Odoo','Odoo Silver']::text[], 'Société partenaire Odoo (niveau Silver affiché par l''éditeur) : mise en place, paramétrage et accompagnement des entreprises sur l''ERP Odoo.'),
  ('331662635', null, array['Odoo','Odoo Ready']::text[], 'Société partenaire Odoo (niveau Ready affiché par l''éditeur) : mise en place, paramétrage et accompagnement des entreprises sur l''ERP Odoo.'),
  ('393590310', null, array['Cegid XRP Flex']::text[], 'Société référencée parmi les partenaires distributeurs de Cegid (Cegid XRP Flex) : déploiement et accompagnement des solutions de gestion.'),
  ('800709891', null, array['Cegid','Pennylane']::text[], 'Cabinet d''expertise comptable et de conseil, cité parmi les partenaires de Cegid et de Pennylane pour la mise en place de solutions de gestion.'),
  ('334822129', null, array['Pennylane']::text[], 'Société citée par Pennylane parmi ses partenaires intégrateurs auprès des PME : mise en place et accompagnement de la solution Pennylane.'),
  ('378914014', 'https://www.ciag.fr', array['Divalto']::text[], 'Société partenaire intégrateur de Divalto : déploiement, paramétrage et accompagnement des entreprises sur les solutions ERP et CRM Divalto.'),
  ('788267599', null, array['Divalto']::text[], 'Société partenaire intégrateur de Divalto : déploiement, paramétrage et accompagnement des entreprises sur les solutions ERP et CRM Divalto.'),
  ('500725601', 'https://www.inelys-rse.fr', array['bilan carbone','RSE']::text[], 'Cabinet de conseil en stratégie climat et bas-carbone, référencé dans l''annuaire des acteurs de la transformation durable de la Métropole de Lyon.'),
  ('338338700', 'https://www.michaelpage.fr', array['finance','comptabilité']::text[], 'Cabinet de recrutement intervenant sur les fonctions finance et comptabilité (DAF, contrôle de gestion, comptables).'),
  ('490047057', 'https://www.robertwalters.fr', array['finance','comptabilité','management de transition']::text[], 'Cabinet de recrutement intervenant sur les fonctions finance et comptabilité (DAF, contrôle de gestion, comptables) ; propose aussi du management de transition.'),
  ('813609468', 'https://ndrh-recrutement.fr', array['finance','comptabilité']::text[], 'Cabinet de recrutement intervenant sur les fonctions finance et comptabilité (DAF, contrôle de gestion, comptables).'),
  ('827609181', null, array['management de transition']::text[], 'Société de management de transition, citée au classement Leaders League 2025 du management de transition.')
) as x(siren, website, specialties, description)
where p.siren = x.siren and p.status = 'draft';

insert into public.provider_categories (provider_id, category_id)
select p.id, c.id from (values
  ('844071324', 'integrateurs-comptables'),
  ('331662635', 'integrateurs-comptables'),
  ('393590310', 'integrateurs-comptables'),
  ('800709891', 'integrateurs-comptables'),
  ('334822129', 'integrateurs-comptables'),
  ('378914014', 'integrateurs-comptables'),
  ('788267599', 'integrateurs-comptables'),
  ('500725601', 'conseil-csrd-carbone'),
  ('338338700', 'cabinets-recrutement-finance'),
  ('490047057', 'cabinets-recrutement-finance'),
  ('490047057', 'management-transition'),
  ('813609468', 'cabinets-recrutement-finance'),
  ('827609181', 'management-transition')
) as x(siren, cat)
join public.providers p on p.siren = x.siren
join public.categories c on c.slug = x.cat and c.site_id = '10000000-0000-4000-a000-000000000001'
on conflict do nothing;

