join public.categories c on c.slug = x.cat and c.site_id = '10000000-0000-4000-a000-000000000001'
on conflict do nothing;

-- Nettoyage : une seule fiche par SIREN (doublons de brouillons issus de deux recherches).
-- La fiche gardée est celle dont l'adresse est la plus courte ; elle reçoit les catégories de l'autre.
with ranked as (
  select id, siren, row_number() over (partition by siren order by length(slug), slug) as rn
  from public.providers where siren is not null and status = 'draft' and not is_fictional
)
insert into public.provider_categories (provider_id, category_id)
select k.id, pc.category_id
from ranked d join ranked k on k.siren = d.siren and k.rn = 1
join public.provider_categories pc on pc.provider_id = d.id
where d.rn > 1
on conflict do nothing;

with ranked as (
  select id, siren, row_number() over (partition by siren order by length(slug), slug) as rn
  from public.providers where siren is not null and status = 'draft' and not is_fictional
)
delete from public.providers where id in (select id from ranked where rn > 1);
